using System;using System.IO;using System.Reflection;using System.Text;using System.Security.Cryptography;
namespace Lumina {
 internal static class CreatorIdentityProof {
  internal const string AuthorName="森霖Sama",DouyinId="Senlin_Sama";
  internal const string Payload64="";
  internal const string Signature64="";
  internal const string PublicKeyXml="<RSAKeyValue><Modulus></Modulus><Exponent>AQAB</Exponent></RSAKeyValue>";
  internal static bool VerifySignature(byte[] payload,byte[] signature){try{using(var rsa=new RSACryptoServiceProvider()){rsa.PersistKeyInCsp=false;rsa.FromXmlString(PublicKeyXml);return rsa.VerifyData(payload,CryptoConfig.MapNameToOID("SHA256"),signature);}}catch(CryptographicException){return false;}}
  static string Expected(string name){byte[] data=Convert.FromBase64String(Payload64);if(!VerifySignature(data,Convert.FromBase64String(Signature64)))throw new InvalidDataException("作者信息签名无效，请使用官方原版。");string text=Encoding.UTF8.GetString(data);if(!text.StartsWith("author="+AuthorName+"\ndouyin="+DouyinId+"\n",StringComparison.Ordinal))throw new InvalidDataException("作者署名与签名不一致。");foreach(string line in text.Split('\n'))if(line.StartsWith(name+"|",StringComparison.Ordinal))return line.Substring(name.Length+1);throw new InvalidDataException("资源未列入签名清单："+name);}
  static void VerifyBytes(string name,byte[] bytes){using(var sha=SHA256.Create()){string hash=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();if(!string.Equals(hash,Expected(name),StringComparison.Ordinal))throw new InvalidDataException("作者素材或独立模块已被替换，请重新解压官方原版。");}}
  internal static void VerifyResource(string name){using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream(name)){if(stream==null)throw new InvalidDataException("作者素材缺失。");using(var data=new MemoryStream()){stream.CopyTo(data);VerifyBytes(name,data.ToArray());}}}
  internal static void VerifyModule(string path,string relative){VerifyBytes(relative,File.ReadAllBytes(path));}
 }
}
